CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE cities (id text PRIMARY KEY, name text NOT NULL, enabled boolean NOT NULL DEFAULT false, base_fare_paise integer NOT NULL CHECK(base_fare_paise>=0), currency text NOT NULL DEFAULT 'INR');
INSERT INTO cities(id,name,base_fare_paise) VALUES ('hyderabad','Hyderabad',24900),('bengaluru','Bengaluru',29900),('delhi-ncr','Delhi NCR',29900),('mumbai','Mumbai',34900),('visakhapatnam','Visakhapatnam',24900),('vijayawada','Vijayawada',24900);
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), oidc_subject text UNIQUE NOT NULL, role text NOT NULL CHECK(role IN ('customer','driver','admin')), disabled boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE drivers (user_id uuid PRIMARY KEY REFERENCES users(id), city_id text NOT NULL REFERENCES cities(id), approved boolean NOT NULL DEFAULT false, online boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE bookings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES users(id), driver_id uuid REFERENCES drivers(user_id), city_id text NOT NULL REFERENCES cities(id), pickup text NOT NULL, destination text NOT NULL, transmission text NOT NULL CHECK(transmission IN ('manual','automatic')), trip_type text NOT NULL CHECK(trip_type IN ('one-way','return','hourly','outstation')), scheduled_at timestamptz, quoted_fare_paise integer NOT NULL CHECK(quoted_fare_paise>=0), status text NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','assigned','arrived','in_progress','completed','cancelled')), idempotency_key uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(customer_id,idempotency_key));
CREATE INDEX bookings_city_status_time ON bookings(city_id,status,created_at DESC);
CREATE INDEX bookings_customer_time ON bookings(customer_id,created_at DESC);
CREATE UNIQUE INDEX one_active_trip_per_driver ON bookings(driver_id) WHERE driver_id IS NOT NULL AND status IN ('assigned','arrived','in_progress');
CREATE TABLE audit_events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, actor_id uuid REFERENCES users(id), booking_id uuid REFERENCES bookings(id), action text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES bookings(id), topic text NOT NULL, delivered_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX pending_outbox ON outbox(created_at) WHERE delivered_at IS NULL;
CREATE TABLE trip_pins (booking_id uuid PRIMARY KEY REFERENCES bookings(id),pin_hash text NOT NULL,attempts integer NOT NULL DEFAULT 0,expires_at timestamptz NOT NULL);
